/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'S3 Palletizing';
  const equipment = {};

  // slab: Epoxy floor slab for a station cell with yellow boundary lines and an...
  equipment.slab = registry.buildComponent('floorSlab', {
    length: 10.6,
    depth: 5.8,
    walkway: 0.55,
  }, ctx);
  equipment.slab.root.position.set(1.2, 0, 1.6);
  root.add(equipment.slab.root);

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', {
    length: 4.8,
    beltWidth: 1.05,
    guides: false,
    drive: false,
    carries: 'case',
  }, { ...ctx, beltHeight: 0.82 });
  root.add(equipment.belt.root);

  // source: Case source enclosure at the head of a conveyor: cases come out of its exit...
  equipment.source = registry.buildComponent('caseSource', {
    depth: 1.55,
    width: 1.45,
    height: 1.85,
    caseHeight: 0.42,
    rearPort: true,
  }, { ...ctx, beltHeight: 0.82 });
  equipment.source.root.position.set(-2.4, 0, 0);
  root.add(equipment.source.root);

  // robot: ABB IRB 6760 six-axis robot (reference model) with a vacuum pad gripper...
  equipment.robot = registry.buildComponent('abbIrb6760', {}, ctx);
  equipment.robot.root.position.set(0.90097, 0, 1.408);
  equipment.robot.root.rotation.y = Math.PI;
  root.add(equipment.robot.root);

  // pallet: Wooden block pallet (deck boards, blocks, bottom boards) that cases are...
  equipment.pallet = registry.buildComponent('blockPallet', { length: 2.06, width: 1.46 }, ctx);
  equipment.pallet.root.position.set(0.14, 0, 2.84);
  root.add(equipment.pallet.root);

  // bay: Translucent coloured floor marking for a bay (dispatch, reject, buffer area)
  equipment.bay = registry.buildComponent('bayMarking', {
    length: 2.3,
    width: 1.1,
    color: 'yellow',
  }, ctx);
  equipment.bay.root.position.set(-2.06, 0, 2.84);
  root.add(equipment.bay.root);

  // worker: Worker with a high-lift pallet truck: drives under a pallet, lifts it...
  equipment.worker = registry.buildComponent('palletJackWorker', { travel: 7 }, ctx);
  equipment.worker.root.position.set(-2.26, 0, 2.84);
  root.add(equipment.worker.root);

  // wrapper: Turntable stretch wrapper: the load turns on a deck while a film carriage...
  equipment.wrapper = registry.buildComponent('stretchWrapper', { deckHeight: 0.44 }, ctx);
  equipment.wrapper.root.position.set(4.34, 0, 2.84);
  root.add(equipment.wrapper.root);

  return { root, equipment };
}
